import json,random
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
DATA=ROOT/'app/campus'
subjects={s['id']:s for s in json.loads((DATA/'data.json').read_text())['subjects']}
output={}
def bank(text):
 rows=[]
 for line in text.strip().splitlines():
  if not line.strip():continue
  parts=line.split('|')
  assert len(parts)==6,parts
  q,right,*rest=parts;wrong=rest[:3];explanation=rest[3]
  rows.append(dict(prompt=q,options=[right,*wrong],answer=0,explanation=explanation))
 return rows
def build(sid,questions,count,format,rules,sources,scope='',open_questions=None):
 assert len(questions)>=count
 models=[]
 for m in range(3):
  chosen=[dict(questions[(m*(len(questions)//3)+i)%len(questions)]) for i in range(count)]
  rng=random.Random(sid+str(m));rng.shuffle(chosen)
  for q in chosen:
   options=list(enumerate(q['options']));rng.shuffle(options)
   q['options']=[s for _,s in options];q['answer']=next(i for i,(old,_) in enumerate(options) if old==0)
  models.append(dict(id=f'{sid}-{m+1}',title=f'Modelo {m+1}',questions=chosen,openQuestions=(open_questions or [[],[],[]])[m]))
 output[sid]=dict(format=format,rules=rules,sources=sources,scope=scope,models=models)
